function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // graduation cap
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2 - 15, H/2 - 30, 30, 10);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2, H/2 - 40 + 20 * Math.sin(t));
  ctx.stroke();

  // confetti
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(W/2 + 50 * Math.cos(i + t), H/2 - 50 * Math.sin(i + t), 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
